          var a = document.activeElement;
          if (S.pop && !S.pop.contains(a) && a !== S.input) close(false);
        }, 0);
      });
      S.pop = pop;
      render();
      document.body.appendChild(pop);
      S.onOutside = function (e) { if (S.pop && !S.pop.contains(e.target) && !S.wrap.contains(e.target)) close(false); };
